DROP TRIGGER IF EXISTS `tg_products_sell_before_insert`;
DELIMITER $$
CREATE TRIGGER `tg_products_sell_before_insert` BEFORE INSERT ON `products_sell` FOR EACH ROW BEGIN
  -- Declare a variable to hold the numeric part of the ID
  DECLARE next_id_num INT;

  -- Find the highest existing number in the PRODUCT_ID column.
  -- CAST is used to sort numbers correctly (e.g., 10 is greater than 9).
  -- IFNULL handles the case where the table is empty, starting the count at 0.
  SELECT IFNULL(MAX(CAST(SUBSTRING(PRODUCT_ID, 3) AS UNSIGNED)), 0) + 1
  INTO next_id_num
  FROM products_sell;

  -- Set the NEW row's PRODUCT_ID to the formatted value 'PD' + '0001', '0002', etc.
  -- LPAD pads the number with leading zeros to a total length of 4.
  SET NEW.PRODUCT_ID = CONCAT('PD', LPAD(next_id_num, 4, '0'));
END
$$
DELIMITER ;
